def chunked(iterable, n, strict=False):
    """Break *iterable* into lists of length *n*:

        >>> list(chunked([1, 2, 3, 4, 5, 6], 3))
        [[1, 2, 3], [4, 5, 6]]

    By the default, the last yielded list will have fewer than *n* elements
    if the length of *iterable* is not divisible by *n*:

        >>> list(chunked([1, 2, 3, 4, 5, 6, 7, 8], 3))
        [[1, 2, 3], [4, 5, 6], [7, 8]]

    To use a fill-in value instead, see the :func:`grouper` recipe.

    If the length of *iterable* is not divisible by *n* and *strict* is
    ``True``, then ``ValueError`` will be raised before the last
    list is yielded.

    """
    if n is not None and n < 0:
        raise ValueError('n must be at least 0')

    iterator = iter(partial(take, n, iter(iterable)), [])
    if strict:
        if n is None:
            raise ValueError('n must not be None when using strict mode.')

        def ret():
            for chunk in iterator:
                if len(chunk) != n:
                    raise ValueError('iterable is not divisible by n.')
                yield chunk

        return ret()
    else:
        return iterator

def ret():
    for chunk in iterator:
        if len(chunk) != n:
            raise ValueError('iterable is not divisible by n.')
        yield chunk

def last(iterable, default=_marker):
    """Return the last item of *iterable*, or *default* if *iterable* is
    empty.

        >>> last([0, 1, 2, 3])
        3
        >>> last([], 'some default')
        'some default'

    If *default* is not provided and there are no items in the iterable,
    raise ``ValueError``.
    """
    try:
        if getattr(iterable, '__reversed__', None):
            return next(reversed(iterable))
        return deque(iterable, maxlen=1)[-1]
    except (IndexError, StopIteration):
        if default is _marker:
            raise ValueError(
                'last() was called on an empty iterable, '
                'and no default value was provided.'
            )
        return default

def __init__(self, iterable):
    self._it = iter(iterable)
    self._cache = deque()

def __bool__(self):
    try:
        self.peek()
    except StopIteration:
        return False
    return True

def peek(self, default=_marker):
    """Return the item that will be next returned from ``next()``.

    Return ``default`` if there are no items left. If ``default`` is not
    provided, raise ``StopIteration``.

    """
    if not self._cache:
        try:
            self._cache.append(next(self._it))
        except StopIteration:
            if default is _marker:
                raise
            return default
    return self._cache[0]

def __next__(self):
    if self._cache:
        return self._cache.popleft()

    return next(self._it)

def _get_slice(self, index):
    # Normalize the slice's arguments
    step = 1 if (index.step is None) else index.step
    if step > 0:
        start = 0 if (index.start is None) else index.start
        stop = maxsize if (index.stop is None) else index.stop
    elif step < 0:
        start = -1 if (index.start is None) else index.start
        stop = (-maxsize - 1) if (index.stop is None) else index.stop
    else:
        raise ValueError('slice step cannot be zero')

    # If either the start or stop index is negative, we'll need to cache
    # the rest of the iterable in order to slice from the right side.
    # When step < 0 and stop is None, the slice stops at index 0 rather than
    # indexing from the right, so only items up to start must be cached.
    has_negative_index = (
        (index.start is not None and index.start < 0)
        or (index.stop is not None and index.stop < 0)
        or (step < 0 and index.start is None)
    )
    if has_negative_index:
        self._cache.extend(self._it)
    # Otherwise we'll need to find the rightmost index and cache to that
    # point.
    else:
        rightmost = (
            start
            if (step < 0 and index.stop is None)
            else max(start, stop)
        )
        n = min(rightmost + 1, maxsize)
        cache_len = len(self._cache)
        if n >= cache_len:
            self._cache.extend(islice(self._it, n - cache_len))

    return list(self._cache)[index]

def __getitem__(self, index):
    if isinstance(index, slice):
        return self._get_slice(index)

    cache_len = len(self._cache)
    if index < 0:
        self._cache.extend(self._it)
    elif index >= cache_len:
        self._cache.extend(islice(self._it, index + 1 - cache_len))

    return self._cache[index]

@wraps(func)
def wrapper(*args, **kwargs):
    gen = func(*args, **kwargs)
    next(gen)
    return gen

def __init__(self, iterable, length):
    self._iterator = iter(iterable)
    self._length = length

def _full(A):
    while True:
        # Yield the permutation we have
        yield tuple(A)

        # Find the largest index i such that A[i] < A[i + 1]
        for i in range(size - 2, -1, -1):
            if A[i] < A[i + 1]:
                break
        #  If no such index exists, this permutation is the last one
        else:
            return

        # Find the largest index j greater than j such that A[i] < A[j]
        for j in range(size - 1, i, -1):
            if A[i] < A[j]:
                break

        # Swap the value of A[i] with that of A[j], then reverse the
        # sequence from A[i + 1] to form the new permutation
        A[i], A[j] = A[j], A[i]
        A[i + 1 :] = A[: i - size : -1]  # A[i + 1:][::-1]

def permuted_items(permuted_indices):
    return tuple(
        next(equivalent_items[index]) for index in permuted_indices
    )

def __contains__(self, value):
    if not self._validator(value):
        return False

    try:
        item = next(self[value])
    except StopIteration:
        return False
    else:
        self._cache[value].appendleft(item)

    return True

def _get_values(self, value):
    """
    Helper to yield items from the parent iterator that match *value*.
    Items that don't match are stored in the local cache as they
    are encountered.
    """
    while True:
        # If we've cached some items that match the target value, emit
        # the first one and evict it from the cache.
        if self._cache.get(value):
            yield self._cache[value].popleft()
        # Otherwise we need to advance the parent iterator to search for
        # a matching item, caching the rest.
        else:
            while True:
                try:
                    item = next(self._it)
                except StopIteration:
                    return
                item_value = self._key(item)
                if item_value == value:
                    if value not in self._cache:
                        self._cache[value] = deque()
                    yield item
                    break
                elif self._validator(item_value):
                    self._cache[item_value].append(item)

def __iter__(self):
    for item in self._it:
        item_value = self._key(item)
        if self._validator(item_value):
            self._cache[item_value].append(item)

    return iter(self._cache)

def __getitem__(self, value):
    if not self._validator(value):
        return iter(())

    return self._get_values(value)

def sliced(seq, n, strict=False):
    """Yield slices of length *n* from the sequence *seq*.

    >>> list(sliced((1, 2, 3, 4, 5, 6), 3))
    [(1, 2, 3), (4, 5, 6)]

    By the default, the last yielded slice will have fewer than *n* elements
    if the length of *seq* is not divisible by *n*:

    >>> list(sliced((1, 2, 3, 4, 5, 6, 7, 8), 3))
    [(1, 2, 3), (4, 5, 6), (7, 8)]

    If the length of *seq* is not divisible by *n* and *strict* is
    ``True``, then ``ValueError`` will be raised before the last
    slice is yielded.

    This function will only work for iterables that support slicing.
    For non-sliceable iterables, see :func:`chunked`.

    """
    if n < 0:
        raise ValueError('n must be at least 0')

    iterator = takewhile(len, (seq[i : i + n] for i in count(0, n)))
    if strict:

        def ret():
            for _slice in iterator:
                if len(_slice) != n:
                    raise ValueError("seq is not divisible by n.")
                yield _slice

        return ret()
    else:
        return iterator

def ret():
    for _slice in iterator:
        if len(_slice) != n:
            raise ValueError("seq is not divisible by n.")
        yield _slice

def slice_generator():
    for first in iterator:
        yield (first,)
        yield islice(iterator_with_repeat, n - 1)

def repeat_each(iterable, n=2):
    """Repeat each element in *iterable* *n* times.

    >>> list(repeat_each('ABC', 3))
    ['A', 'A', 'A', 'B', 'B', 'B', 'C', 'C', 'C']
    """
    return chain.from_iterable(map(repeat, iterable, repeat(n)))

def zip_offset(*iterables, offsets, longest=False, fillvalue=None):
    """``zip`` the input *iterables* together, but offset the `i`-th iterable
    by the `i`-th item in *offsets*.

        >>> list(zip_offset('0123', 'abcdef', offsets=(0, 1)))
        [('0', 'b'), ('1', 'c'), ('2', 'd'), ('3', 'e')]

    This can be used as a lightweight alternative to SciPy or pandas to analyze
    data sets in which some series have a lead or lag relationship.

    By default, the sequence will end when the shortest iterable is exhausted.
    To continue until the longest iterable is exhausted, set *longest* to
    ``True``.

        >>> list(zip_offset('0123', 'abcdef', offsets=(0, 1), longest=True))
        [('0', 'b'), ('1', 'c'), ('2', 'd'), ('3', 'e'), (None, 'f')]

    By default, ``None`` will be used to replace offsets beyond the end of the
    sequence. Specify *fillvalue* to use some other value.

    """
    if len(iterables) != len(offsets):
        raise ValueError("Number of iterables and offsets didn't match")

    staggered = []
    for it, n in zip(iterables, offsets):
        if n < 0:
            staggered.append(chain(repeat(fillvalue, -n), it))
        elif n > 0:
            staggered.append(islice(it, n, None))
        else:
            staggered.append(it)

    if longest:
        return zip_longest(*staggered, fillvalue=fillvalue)

    return zip(*staggered)

