    if isinstance(key, slice):
        return islice_extended(_islice_helper(self._iterator, key))

    raise TypeError('islice_extended.__getitem__ argument must be a slice')

def always_reversible(iterable):
    """An extension of :func:`reversed` that supports all iterables, not
    just those which implement the ``Reversible`` or ``Sequence`` protocols.

        >>> print(*always_reversible(x for x in range(3)))
        2 1 0

    If the iterable is already reversible, this function returns the
    result of :func:`reversed()`. If the iterable is not reversible,
    this function will cache the remaining items in the iterable and
    yield them in reverse order, which may require significant storage.
    """
    try:
        return reversed(iterable)
    except TypeError:
        return reversed(list(iterable))

def __init__(self, target):
    if not isinstance(target, Sequence):
        raise TypeError
    self._target = target

def __init__(self, iterable, maxlen=None):
    self._maxlen_zero = maxlen == 0
    self._source = (
        peekable(iterable) if self._maxlen_zero else iter(iterable)
    )
    if maxlen is None:
        self._cache = []
    else:
        self._cache = deque([], maxlen)
    self._index = None

def __next__(self):
    if self._index is not None:
        try:
            item = self._cache[self._index]
        except IndexError:
            self._index = None
        else:
            self._index += 1
            return item

    item = next(self._source)
    self._cache.append(item)
    return item

def __bool__(self):
    try:
        self.peek()
    except StopIteration:
        return False
    return True

def peek(self, default=_marker):
    if self._maxlen_zero:
        return self._source.peek(default)
    try:
        peeked = next(self)
    except StopIteration:
        if default is _marker:
            raise
        return default
    if self._index is None:
        self._index = len(self._cache)
    self._index -= 1
    return peeked

def seek(self, index):
    self._index = index
    remainder = index - len(self._cache)
    if remainder > 0:
        consume(self, remainder)

def relative_seek(self, count):
    if self._index is None:
        self._index = len(self._cache)

    self.seek(max(self._index + count, 0))

class run_length:
    """
    :func:`run_length.encode` compresses an iterable with run-length encoding.
    It yields groups of repeated items with the count of how many times they
    were repeated:

        >>> uncompressed = 'abbcccdddd'
        >>> list(run_length.encode(uncompressed))
        [('a', 1), ('b', 2), ('c', 3), ('d', 4)]

    :func:`run_length.decode` decompresses an iterable that was previously
    compressed with run-length encoding. It yields the items of the
    decompressed iterable:

        >>> compressed = [('a', 1), ('b', 2), ('c', 3), ('d', 4)]
        >>> list(run_length.decode(compressed))
        ['a', 'b', 'b', 'c', 'c', 'c', 'd', 'd', 'd', 'd']

    """

    @staticmethod
    def encode(iterable):
        return ((k, ilen(g)) for k, g in groupby(iterable))

    @staticmethod
    def decode(iterable):
        return chain.from_iterable(starmap(repeat, iterable))

@staticmethod
